-- Old-dungeon creatures that cast these spells on live but never did here (data farm handover, 19 Nov). Which spells: EG Link
-- combat logs from the live realm (https://efficient.games), CC BY 4.0, builds 70205-70959. Timers and targets: the VMaNGOS world
-- database (github.com/brotalnia/database, 14 June 2021, GPL-2), creature_spells and creature_ai_events.
-- Sneed's Disarm, Quick Flame Ward on Defias Evoker and Defias Wizard (cast on themselves when aura not present), Frostbolt Volley
-- and Frost Nova on Aku'mai Servant (SmartAI on, no rows: it only meleed), Noxious Catalyst and Corruption on Noxxious Scion.
-- Same rules as 2026_11_19_85: ids 100+ with an 'EG live' comment, and a row is only added when nothing else of the creature
-- already casts that spell. Safe to run again.

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` IN (643,1729,4418,4978,13696) AND `AIName` = '' AND `ScriptName` = '';
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (643,1729,4418,4978,13696) AND `id` >= 100 AND `comment` LIKE 'EG live%';
INSERT INTO `smart_scripts` (`entryorguid`,`source_type`,`id`,`link`,`Difficulties`,`event_type`,`event_phase_mask`,`event_chance`,`event_flags`,`event_param1`,`event_param2`,`event_param3`,`event_param4`,`event_param5`,`event_param_string`,`action_type`,`action_param1`,`action_param2`,`action_param3`,`action_param4`,`action_param5`,`action_param6`,`action_param7`,`action_param_string`,`target_type`,`target_param1`,`target_param2`,`target_param3`,`target_param4`,`target_param_string`,`target_x`,`target_y`,`target_z`,`target_o`,`comment`)
SELECT 643,0,100,0,'',0,0,100,0,7000,17000,15000,20000,0,'',11,6713,0,0,0,0,0,0,'',2,0,0,0,0,'',0,0,0,0,'EG live: Sneed - Disarm (6713), VMaNGOS timers' FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `smart_scripts` s WHERE s.`entryorguid` = 643 AND s.`source_type` = 0 AND s.`action_type` = 11 AND s.`action_param1` = 6713);
